import { createClient } from '@supabase/supabase-js';
import { QwenProvider } from '../src/lib/ai/providers/qwen';

const SUPABASE_URL = process.env.NEXT_PUBLIC_SUPABASE_URL!;
const SUPABASE_SERVICE_ROLE_KEY = process.env.SUPABASE_SERVICE_ROLE_KEY!;

async function run() {
  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
  
  // Find a walk in ANALYZING state
  const { data: walks } = await supabase.from('walks').select('id, user_id').eq('status', 'ANALYZING').limit(1);
  if (!walks || walks.length === 0) {
    console.log("No walk found in ANALYZING state.");
    return;
  }
  
  const walk = walks[0];
  console.log(`Found walk in ANALYZING state: ${walk.id}. Simulating AI analysis...`);
  
  const { data: photos } = await supabase.from('walk_photos').select('*').eq('walk_id', walk.id).order('sort_order');
  
  const aiProvider = new QwenProvider();
  
  // Create signed URLs
  const imageUrls = await Promise.all(
    (photos || []).map(async (p: any, idx: number) => {
      const { data } = await supabase.storage.from('walk-photos').createSignedUrl(p.storage_path, 60 * 60);
      return { url: data?.signedUrl || '', order: idx };
    })
  );
  
  try {
    const aiResult = await aiProvider.analyzeWalk({ images: imageUrls, outputLanguage: 'ja' });
    console.log("AI Result:", JSON.stringify(aiResult, null, 2));
    
    console.log("Calling save_discovery_analysis RPC...");
    const { data: rpcData, error: rpcError } = await supabase.rpc('save_discovery_analysis', {
      p_walk_id: walk.id,
      p_title: aiResult.title,
      p_tags: aiResult.tags,
    });
    
    if (rpcError) throw rpcError;
    console.log("RPC Success!");
    
    // Verify DB state
    const { data: walkData } = await supabase.from('walks').select('status, title').eq('id', walk.id).single();
    console.log("Walk Status after RPC:", walkData?.status);
    console.log("Walk Title after RPC:", walkData?.title);
    
    const { data: tags } = await supabase.from('discovery_tags').select('*').eq('walk_id', walk.id);
    console.log(`Found ${tags?.length} discovery tags for walk.`);
  } catch (err: any) {
    console.error("FAIL:", err.message);
  }
}

run().catch(console.error);

import { createClient } from '@supabase/supabase-js';

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL;
const supabaseServiceKey = process.env.SUPABASE_SERVICE_ROLE_KEY;

if (!supabaseUrl || !supabaseServiceKey) {
  console.error('Error: NEXT_PUBLIC_SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY must be set.');
  console.error('Run this script using: npx tsx --env-file=.env.local scripts/seed-demo.ts <user_id>');
  process.exit(1);
}

const supabase = createClient(supabaseUrl, supabaseServiceKey);

async function seedDemo(userId: string) {
  console.log(`Seeding demo data for user: ${userId}`);

  // Walk 1: 横須賀
  const { data: walk1, error: err1 } = await supabase.from('walks').insert({
    user_id: userId,
    status: 'COMPLETED',
    title: '異国文化が残る港町を歩く',
    location: '横須賀',
    created_at: new Date(Date.now() - 3 * 24 * 60 * 60 * 1000).toISOString(),
    completed_at: new Date(Date.now() - 3 * 24 * 60 * 60 * 1000 + 1000 * 60 * 5).toISOString(),
  }).select('id').single();
  if (err1) throw err1;

  // Walk 1 Tags
  const { data: tag1_1, error: terr1 } = await supabase.from('discovery_tags').insert({
    walk_id: walk1.id,
    label: '港町の日常',
    category: 'Local Life',
    reason: '港町の雰囲気が強く感じられる風景でした。',
    selected: true,
  }).select('id').single();
  if (terr1) throw terr1;

  const { data: tag1_2, error: terr2 } = await supabase.from('discovery_tags').insert({
    walk_id: walk1.id,
    label: '異文化が混ざる街',
    category: 'Culture',
    reason: '日本と海外の文化が混ざり合った独特な街並み。',
    selected: true,
  }).select('id').single();
  if (terr2) throw terr2;

  // Walk 1 Recommendation Set
  const { data: set1, error: serr1 } = await supabase.from('recommendation_sets').insert({
    walk_id: walk1.id,
    search_query: '東京 港町の日常 異文化が混ざる街 散歩 街歩き おすすめ場所 観光 名所',
    search_provider: 'none',
    ai_provider: 'openai',
  }).select('id').single();
  if (serr1) throw serr1;

  // Walk 1 Recommended Place
  const { data: place1, error: perr1 } = await supabase.from('recommended_places').insert({
    recommendation_set_id: set1.id,
    name: '福生ベースサイドストリート',
    area: '福生市',
    description: '横田基地に面した国道16号沿いのエリア。アメリカの雰囲気が漂うカフェや雑貨店が立ち並び、異国情緒あふれる街歩きが楽しめます。',
    google_maps_query: '福生ベースサイドストリート 福生市 東京',

  }).select('id').single();
  if (perr1) throw perr1;

  await supabase.from('recommended_place_tags').insert({
    recommended_place_id: place1.id,
    discovery_tag_id: tag1_2.id,
  });


  // Walk 2: 谷根千
  const { data: walk2, error: err2 } = await supabase.from('walks').insert({
    user_id: userId,
    status: 'COMPLETED',
    title: '下町の路地裏探索',
    location: '谷中',
    created_at: new Date(Date.now() - 1 * 24 * 60 * 60 * 1000).toISOString(),
    completed_at: new Date(Date.now() - 1 * 24 * 60 * 60 * 1000 + 1000 * 60 * 5).toISOString(),
  }).select('id').single();
  if (err2) throw err2;

  // Walk 2 Tags
  const { data: tag2_1, error: terr2_1 } = await supabase.from('discovery_tags').insert({
    walk_id: walk2.id,
    label: '昭和レトロな街並み',
    category: 'Architecture',
    reason: '古い木造建築や細い路地が残っていました。',
    selected: true,
  }).select('id').single();
  if (terr2_1) throw terr2_1;

  // Walk 2 Recommendation Set
  const { data: set2, error: serr2 } = await supabase.from('recommendation_sets').insert({
    walk_id: walk2.id,
    search_query: '東京 昭和レトロな街並み 散歩 街歩き おすすめ場所 観光 名所',
    search_provider: 'none',
    ai_provider: 'openai',
  }).select('id').single();
  if (serr2) throw serr2;

  // Walk 2 Recommended Place
  const { data: place2, error: perr2 } = await supabase.from('recommended_places').insert({
    recommendation_set_id: set2.id,
    name: '柴又帝釈天周辺',
    area: '葛飾区',
    description: '昔ながらの参道や古い建物が残るエリア。映画の舞台にもなった情緒ある風景の中をのんびり歩くことができます。',
    google_maps_query: '柴又帝釈天 葛飾区 東京',
  }).select('id').single();
  if (perr2) throw perr2;

  await supabase.from('recommended_place_tags').insert({
    recommended_place_id: place2.id,
    discovery_tag_id: tag2_1.id,
  });

  // Walk 3: 季節の花
  const { data: walk3, error: err3 } = await supabase.from('walks').insert({
    user_id: userId,
    status: 'COMPLETED',
    title: '季節の花をテーマにした東京の散歩',
    location: null,
    created_at: new Date(Date.now() - 5 * 24 * 60 * 60 * 1000).toISOString(),
    completed_at: new Date(Date.now() - 5 * 24 * 60 * 60 * 1000 + 1000 * 60 * 5).toISOString(),
  }).select('id').single();
  if (err3) throw err3;

  // Walk 3 Tags
  const { data: tag3_1, error: terr3_1 } = await supabase.from('discovery_tags').insert({
    walk_id: walk3.id,
    label: '都市の中の自然',
    category: 'Nature',
    reason: 'コンクリートの間に咲く花が印象的でした。',
    selected: true,
  }).select('id').single();
  if (terr3_1) throw terr3_1;

  // Walk 3 Recommendation Set
  const { data: set3, error: serr3 } = await supabase.from('recommendation_sets').insert({
    walk_id: walk3.id,
    search_query: '東京 都市の中の自然 散歩 街歩き おすすめ場所 観光 名所',
    search_provider: 'none',
    ai_provider: 'openai',
  }).select('id').single();
  if (serr3) throw serr3;

  // Walk 3 Recommended Place
  const { data: place3, error: perr3 } = await supabase.from('recommended_places').insert({
    recommendation_set_id: set3.id,
    name: '等々力渓谷',
    area: '世田谷区',
    description: '東京23区唯一の渓谷で、豊かな自然と四季折々の植物を楽しむことができる、都会のオアシスのような場所です。',
    google_maps_query: '等々力渓谷 世田谷区 東京',
  }).select('id').single();
  if (perr3) throw perr3;

  await supabase.from('recommended_place_tags').insert({
    recommended_place_id: place3.id,
    discovery_tag_id: tag3_1.id,
  });

  console.log('Demo data seeded successfully!');
}

const targetUserId = process.argv[2];

if (!targetUserId) {
  console.error('Usage: ts-node scripts/seed-demo.ts <user_id>');
  process.exit(1);
}

seedDemo(targetUserId).catch((err) => {
  console.error('Failed to seed demo data:', err);
  process.exit(1);
});

import { createClient } from '@supabase/supabase-js';
import OpenAI from 'openai';

async function testQwenText() {
  console.log('--- Testing Qwen Text ---');
  const openai = new OpenAI({
    baseURL: process.env.AI_BASE_URL,
    apiKey: process.env.AI_API_KEY,
  });
  
  try {
    const res = await openai.chat.completions.create({
      model: process.env.AI_TEXT_MODEL || 'qwen3.7-flash',
      messages: [{ role: 'user', content: 'こんにちは、あなたは誰ですか？ JSONで回答してください。' }],
      response_format: { type: 'json_object' }
    });
    console.log('Qwen Text Response:', res.choices[0]?.message?.content);
  } catch (err: any) {
    console.error('Qwen Text Error:', err.status, err.message);
  }
}

async function testQwenVision() {
  console.log('--- Testing Qwen Vision ---');
  const openai = new OpenAI({
    baseURL: process.env.AI_BASE_URL,
    apiKey: process.env.AI_API_KEY,
  });

  try {
    const res = await openai.chat.completions.create({
      model: process.env.AI_VISION_MODEL || 'qwen3.7-plus',
      messages: [{ 
        role: 'user', 
        content: [
          { type: 'text', text: 'What is this image? Reply in JSON format like {"description": "..."}' },
          { type: 'image_url', image_url: { url: 'https://picsum.photos/seed/picsum/200/300' } }
        ] 
      }],
      response_format: { type: 'json_object' }
    });
    console.log('Qwen Vision Response:', res.choices[0]?.message?.content);
  } catch (err: any) {
    console.error('Qwen Vision Error:', err.status, err.message);
  }
}

async function testTavily() {
  console.log('--- Testing Tavily ---');
  try {
    const res = await fetch('https://api.tavily.com/search', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        api_key: process.env.TAVILY_API_KEY,
        query: '東京 散歩',
        include_images: true
      })
    });
    const data = await res.json();
    console.log(`Tavily Results Count: ${data.results?.length}`);
    console.log(`Tavily Images Type: ${Array.isArray(data.images) ? 'Array' : typeof data.images}`);
  } catch (err: any) {
    console.error('Tavily Error:', err.message);
  }
}

async function testSupabase() {
  console.log('--- Testing Supabase ---');
  const supabase = createClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.SUPABASE_SERVICE_ROLE_KEY!);
  
  try {
    const { data, error } = await supabase.from('walks').select('id').limit(1);
    if (error) {
      console.log('Supabase Walks query error (maybe tables missing?):', error.message);
    } else {
      console.log('Supabase Walks query success. Data length:', data.length);
    }
  } catch (err: any) {
    console.error('Supabase Error:', err.message);
  }
}

async function run() {
  await testQwenText();
  await testQwenVision();
  await testTavily();
  await testSupabase();
}

run();

