import { getAIProvider } from "./index";
import { AnalyzeWalkInput } from "./provider";
import { AnalyzeWalkOutput, AnalyzeWalkOutputSchema } from "./schemas";

export async function analyzeWalk(input: AnalyzeWalkInput): Promise<AnalyzeWalkOutput> {
  const provider = getAIProvider("vision");
  
  let result: AnalyzeWalkOutput | null = null;
  let lastError: Error | null = null;
  
  for (let i = 0; i < 2; i++) {
    try {
      const rawResult = await provider.analyzeWalk(input);
      result = AnalyzeWalkOutputSchema.parse(rawResult);
      
      if (result.title.trim().length === 0) {
        throw new Error("Title cannot be empty");
      }
      
      const labels = new Set<string>();
      for (const tag of result.tags) {
        if (labels.has(tag.label)) {
          throw new Error(`Duplicate tag label detected: ${tag.label}`);
        }
        labels.add(tag.label);
      }
      
      // Basic generic label guard
      const genericLabels = ["建物", "道路", "食べ物", "花", "車", "店", "人"];
      for (const tag of result.tags) {
        if (genericLabels.includes(tag.label)) {
          throw new Error(`Generic tag label detected: ${tag.label}`);
        }
      }
      
      return result;
    } catch (err: any) {
      console.warn(`AI Analysis attempt ${i + 1} failed:`, err);
      lastError = err;
    }
  }
  
  throw lastError || new Error("AI analysis failed after retries.");
}

import { getAIProvider } from "./index";
import { GenerateRecommendationsInput } from "./provider";
import { RecommendationOutput, RecommendationOutputSchema } from "./schemas";
import { enrichPlaceResultsWithGooglePlaces } from "@/lib/maps/googlePlaces";

export async function generateRecommendations(
  input: GenerateRecommendationsInput
): Promise<RecommendationOutput> {
  const provider = getAIProvider("recommendation");

  let lastError: Error | null = null;

  for (let attempt = 0; attempt < 2; attempt++) {
    try {
      const raw = await provider.generateRecommendations(input);
      const result = RecommendationOutputSchema.parse(raw);

      const selectedLabels = new Set(
        ((input.selectedFeatures && input.selectedFeatures.length > 0)
          ? input.selectedFeatures
          : (input.selectedTags ?? [])
        ).map((feature) => feature.label)
      );

      const names = new Set<string>();
      for (const place of result.places) {
        if (names.has(place.name)) {
          throw new Error(`Duplicate place name: ${place.name}`);
        }
        names.add(place.name);

        if (!place.googleMapsQuery || place.googleMapsQuery.trim().length === 0) {
          throw new Error(`Missing googleMapsQuery for ${place.name}`);
        }

        for (const matchedFeature of place.matchedFeatures) {
          if (!selectedLabels.has(matchedFeature)) {
            throw new Error(`matchedFeature "${matchedFeature}" is not in the selected feature list`);
          }
        }
      }

      const enrichedResult = await enrichPlaceResultsWithGooglePlaces(result);
      return enrichedResult;
    } catch (err: any) {
      console.warn(`Recommendation attempt ${attempt + 1} failed:`, err.message);
      lastError = err;
    }
  }

  throw lastError || new Error("Recommendation generation failed after retries");
}

import OpenAI from "openai";
import { AIProvider, AnalyzeWalkInput, GenerateRecommendationsInput } from "../provider";
import { AnalyzeWalkOutput, AnalyzeWalkOutputSchema, RecommendationOutput, RecommendationOutputSchema } from "../schemas";
import { getAnalyzeWalkPrompt } from "../prompts/analyzeWalkPrompt";
import { getRecommendPlacesPrompt } from "../prompts/recommendPlacesPrompt";
import { zodResponseFormat } from "openai/helpers/zod";

export class OpenAIProvider implements AIProvider {
  private client: OpenAI;

  constructor() {
    this.client = new OpenAI({
      apiKey: process.env.OPENAI_API_KEY ?? process.env.AI_API_KEY,
      baseURL: process.env.OPENAI_BASE_URL || undefined,
    });
  }

  async analyzeWalk(input: AnalyzeWalkInput): Promise<AnalyzeWalkOutput> {
    const prompt = getAnalyzeWalkPrompt(input.images.length, input.location);
    const model = process.env.OPENAI_VISION_MODEL || process.env.AI_VISION_MODEL || "gpt-4o";

    const content: any[] = [
      { type: "text", text: prompt }
    ];

    const sortedImages = [...input.images].sort((a, b) => a.order - b.order);

    for (const image of sortedImages) {
      content.push({
        type: "image_url",
        image_url: {
          url: image.url,
        }
      });
    }

    const response = await this.client.chat.completions.parse({
      model,
      messages: [
        {
          role: "user",
          content,
        }
      ],
      response_format: zodResponseFormat(AnalyzeWalkOutputSchema, "analyze_walk_output"),
    });

    const parsed = response.choices[0].message.parsed;
    if (!parsed) {
      throw new Error("Failed to parse AI output");
    }

    return parsed;
  }

  async generateRecommendations(input: GenerateRecommendationsInput): Promise<RecommendationOutput> {
    const prompt = getRecommendPlacesPrompt(input);
    const model = process.env.OPENAI_RECOMMENDATION_MODEL || process.env.AI_TEXT_MODEL || "gpt-4o";

    const response = await this.client.chat.completions.parse({
      model,
      messages: [
        {
          role: "user",
          content: prompt,
        }
      ],
      response_format: zodResponseFormat(RecommendationOutputSchema, "recommendation_output"),
    });

    const parsed = response.choices[0].message.parsed;
    if (!parsed) {
      throw new Error("Failed to parse recommendation output");
    }

    return parsed;
  }
}

import OpenAI from "openai";
import { AIProvider, AnalyzeWalkInput, GenerateRecommendationsInput } from "../provider";
import { AnalyzeWalkOutput, AnalyzeWalkOutputSchema, RecommendationOutput, RecommendationOutputSchema } from "../schemas";
import { getAnalyzeWalkPrompt } from "../prompts/analyzeWalkPrompt";
import { getRecommendPlacesPrompt } from "../prompts/recommendPlacesPrompt";
import { logger } from "@/lib/logging/logger";

function normalizeFeatureType(value: string | undefined): "culture" | "style" | "atmosphere" {
  if (value === "Culture") return "culture";
  if (value === "Architecture") return "style";
  if (value === "History") return "culture";
  if (value === "Nature") return "atmosphere";
  if (value === "Local Life") return "atmosphere";
  if (value === "culture" || value === "style" || value === "atmosphere") return value;
  return "style";
}

export class QwenProvider implements AIProvider {
  private client: OpenAI;

  constructor() {
    this.client = new OpenAI({
      apiKey: process.env.QWEN_API_KEY ?? process.env.AI_API_KEY,
      baseURL: process.env.QWEN_BASE_URL ?? process.env.AI_BASE_URL,
    });
  }

  async analyzeWalk(input: AnalyzeWalkInput, retryCount = 0): Promise<AnalyzeWalkOutput> {
    const basePrompt = getAnalyzeWalkPrompt(input.images.length, input.location);
    let prompt = `${basePrompt}\n\nIMPORTANT: You must return the result as a valid JSON object.`;

    if (retryCount > 0) {
      prompt += `\n\nYour previous JSON did not match the required schema.\nEach item in tags MUST have:\n{\n  "label": string,\n  "type": "culture" | "style" | "atmosphere",\n  "reason": string\n}\nReturn the entire corrected JSON object only.`;
    }
    const model = process.env.QWEN_VISION_MODEL || process.env.AI_VISION_MODEL || "qwen-vl-plus";

    const content: any[] = [
      { type: "text", text: prompt }
    ];

    const sortedImages = [...input.images].sort((a, b) => a.order - b.order);

    for (const image of sortedImages) {
      content.push({
        type: "image_url",
        image_url: {
          url: image.url,
        }
      });
    }

    try {
      const response = await this.client.chat.completions.create({
        model,
        messages: [
          {
            role: "user",
            content,
          }
        ],
        response_format: { type: "json_object" },
      });

      const messageContent = response.choices[0]?.message?.content;
      if (!messageContent) {
        throw new Error("Failed to get content from AI output");
      }

      const parsedJson = JSON.parse(messageContent);
      const rawTags = Array.isArray(parsedJson.tags) ? parsedJson.tags : Array.isArray(parsedJson.features) ? parsedJson.features : [];
      parsedJson.tags = rawTags.map((tag: any) => ({
        label: tag.label,
        type: normalizeFeatureType(tag.type ?? tag.category),
        reason: tag.reason,
      }));

      logger.info('Qwen analyze response parsed');
      return AnalyzeWalkOutputSchema.parse(parsedJson);
    } catch (error) {
      logger.error("Qwen analyzeWalk error", error);
      if (retryCount < 1) {
        logger.info("Retrying Qwen analyzeWalk...");
        return this.analyzeWalk(input, retryCount + 1);
      }
      throw new Error("Failed to parse AI output after retries");
    }
  }

  async generateRecommendations(input: GenerateRecommendationsInput, retryCount = 0): Promise<RecommendationOutput> {
    const basePrompt = getRecommendPlacesPrompt(input);
    let prompt = `${basePrompt}\n\nIMPORTANT: You must return the result as a valid JSON object.`;

    if (retryCount > 0) {
      prompt += `\n\nYour previous JSON did not match the required schema.\nReturn the entire corrected JSON object only.`;
    }
    const model = process.env.QWEN_TEXT_MODEL || process.env.AI_TEXT_MODEL || "qwen-plus";

    const response = await this.client.chat.completions.create({
      model,
      messages: [
        {
          role: "user",
          content: prompt,
        }
      ],
      response_format: { type: "json_object" },
    });

    const messageContent = response.choices[0]?.message?.content;
    if (!messageContent) {
      throw new Error("Failed to get content from recommendation output");
    }

    try {
      const parsedJson = JSON.parse(messageContent);
      const normalizedPlaces = (parsedJson.places ?? []).map((place: any) => ({
        ...place,
        matchedFeatures: Array.isArray(place.matchedFeatures) ? place.matchedFeatures : Array.isArray(place.matchedTags) ? place.matchedTags : [],
        type: place.type ?? "place",
        reason: place.reason ?? place.description ?? "",
      }));
      return RecommendationOutputSchema.parse({ ...parsedJson, places: normalizedPlaces });
    } catch (error) {
      logger.error("Qwen generateRecommendations validation error", error);
      if (retryCount < 1) {
        logger.info("Retrying Qwen generateRecommendations...");
        return this.generateRecommendations(input, retryCount + 1);
      }
      throw new Error("Failed to parse recommendation output");
    }
  }
}

import { createClient } from '@/lib/supabase/server';

export interface SavedPlace {
  id: string;
  name: string;
  area: string | null;
  description: string;
  imageUrl: string | null;
  googleMapsQuery: string;
  matchedTags: string[];
  createdAt: string;
}

export async function getSavedPlaces(): Promise<SavedPlace[]> {
  const supabase = await createClient();
  const { data, error } = await supabase
    .from('saved_places')
    .select('id, name, area, description, image_url, google_maps_query, matched_tags, created_at')
    .order('created_at', { ascending: false });

  if (error) throw error;
  if (!data) return [];

  return data.map((row: any) => ({
    id: row.id,
    name: row.name,
    area: row.area,
    description: row.description,
    imageUrl: row.image_url,
    googleMapsQuery: row.google_maps_query,
    matchedTags: Array.isArray(row.matched_tags) ? row.matched_tags : [],
    createdAt: row.created_at,
  }));
}

import { SearchProvider } from "./provider";
import { SearchPlacesInput, SearchResult } from "./types";
import { logger } from "@/lib/logging/logger";

function extractImageUrl(item: unknown): string | null {
  if (typeof item === 'string' && item.startsWith('http')) return item;
  if (item && typeof item === 'object') {
    const obj = item as Record<string, unknown>;
    // Handle shapes like { url: '...' } or { src: '...' }
    if (typeof obj.url === 'string' && obj.url.startsWith('http')) return obj.url;
    if (typeof obj.src === 'string' && obj.src.startsWith('http')) return obj.src;
  }
  return null;
}

export class TavilySearchProvider implements SearchProvider {
  async searchPlaces(input: SearchPlacesInput): Promise<SearchResult[]> {
    const apiKey = process.env.TAVILY_API_KEY;
    if (!apiKey) {
      throw new Error("TAVILY_API_KEY is not set");
    }

    const response = await fetch("https://api.tavily.com/search", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        api_key: apiKey,
        query: input.query,
        search_depth: "basic",
        include_images: true,
        max_results: input.maxResults,
        include_domains: input.includeDomains,
        exclude_domains: input.excludeDomains,
      }),
    });

    if (!response.ok) {
      throw new Error(`Tavily search failed: ${response.status} ${response.statusText}`);
    }

    const data = await response.json();

    if (!Array.isArray(data.results)) {
      logger.warn('Tavily response missing results array', typeof data.results);
      return [];
    }

    const results: SearchResult[] = data.results.map((r: any) => ({
      title: r.title ?? '',
      url: r.url ?? '',
      content: r.content ?? '',
      score: r.score,
      imageUrl: null,
    }));

    // Harden: images may be string[] or object[] with varying shapes
    if (Array.isArray(data.images)) {
      data.images.forEach((item: unknown, i: number) => {
        if (i >= results.length) return;
        try {
          results[i].imageUrl = extractImageUrl(item);
        } catch {
          // Image parsing failure must never fail search results
          results[i].imageUrl = null;
        }
      });
    }

    return results;
  }
}

import { createServerClient } from '@supabase/ssr';
import { NextResponse, type NextRequest } from 'next/server';

export async function updateSession(request: NextRequest) {
  let supabaseResponse = NextResponse.next({
    request,
  });

  const supabase = createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll() {
          return request.cookies.getAll();
        },
        setAll(cookiesToSet) {
          cookiesToSet.forEach(({ name, value, options }) => request.cookies.set(name, value));
          supabaseResponse = NextResponse.next({
            request,
          });
          cookiesToSet.forEach(({ name, value, options }) =>
            supabaseResponse.cookies.set(name, value, options)
          );
        },
      },
    }
  );

  // IMPORTANT: Avoid writing any logic between createServerClient and
  // supabase.auth.getUser(). A simple mistake could make it very hard to debug
  // issues with users being randomly logged out.

  await supabase.auth.getUser();

  return supabaseResponse;
}

import { createServerClient } from '@supabase/ssr';
import { cookies } from 'next/headers';
import { Database } from '@/types/database';

export async function createClient() {
  const cookieStore = await cookies();

  return createServerClient<Database>(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll() {
          return cookieStore.getAll();
        },
        setAll(cookiesToSet) {
          try {
            cookiesToSet.forEach(({ name, value, options }) => {
              cookieStore.set(name, value, options);
            });
          } catch (error) {
            // The `set` method was called from a Server Component.
            // This can be ignored if you have middleware refreshing
            // user sessions.
          }
        },
      },
    }
  );
}

