export interface WalkPhoto {
  id: string;
  storagePath: string;
  sortOrder: number;
  signedUrl: string | null;
}

export interface WalkTag {
  id: string;
  label: string;
  category: string;
  selected: boolean;
}

export interface WalkRecommendedPlace {
  id: string;
  name: string;
  area: string | null;
  description: string;
  imageUrl: string | null;
