export interface WalkDetail {
  id: string;
  title: string;
  location: string | null;
  status: string;
  createdAt: string;
  completedAt: string | null;
  photos: WalkPhoto[];
  selectedTags: WalkTag[];
  recommendations: WalkRecommendedPlace[];
}

export async function getWalkDetail(walkId: string): Promise<WalkDetail | null> {
  const supabase = await createClient();

  const { data: { user } } = await supabase.auth.getUser();
  if (!user) return null;

  const { data: walk, error } = await supabase
    .from('walks')
    .select('id, title, location, status, created_at, completed_at')
    .eq('id', walkId)
    .eq('user_id', user.id)
    .single();

  if (error || !walk) return null;

  // Photos
  const { data: photosData } = await supabase
    .from('walk_photos')
    .select('id, storage_path, sort_order')
    .eq('walk_id', walkId)
    .order('sort_order', { ascending: true });

  const photos: WalkPhoto[] = await Promise.all(
    (photosData ?? []).map(async (p: any) => {
      let signedUrl: string | null = null;
      try { signedUrl = await getSignedImageUrl(p.storage_path, 3600); } catch {}
      return { id: p.id, storagePath: p.storage_path, sortOrder: p.sort_order, signedUrl };
    })
  );

  // Tags
  const { data: tagsData } = await supabase
    .from('discovery_tags')
    .select('id, label, category, selected')
    .eq('walk_id', walkId);

  const selectedTags: WalkTag[] = (tagsData ?? [])
    .filter((t: any) => t.selected)
    .map((t: any) => ({ id: t.id, label: t.label, category: t.category, selected: t.selected }));

  // Recommendations
  let recommendations: WalkRecommendedPlace[] = [];
  if (walk.status === 'COMPLETED') {
    const { data: set } = await supabase
      .from('recommendation_sets')
      .select('id')
      .eq('walk_id', walkId)
      .single();

    if (set) {
      const { data: places } = await supabase
        .from('recommended_places')
        .select('id, name, area, description, image_url, google_maps_query, recommended_place_tags(discovery_tags(label))')
        .eq('recommendation_set_id', set.id);

      if (places) {
        const placeIds = places.map((p: any) => p.id);
        const { data: savedRows } = await supabase
          .from('saved_places')
          .select('id, source_recommended_place_id')
          .eq('user_id', user.id)
          .in('source_recommended_place_id', placeIds);

        const savedMap = new Map<string, string>();
        for (const row of savedRows ?? []) {
          if (row.source_recommended_place_id) {
            savedMap.set(row.source_recommended_place_id, row.id);
          }
        }

        recommendations = places.map((p: any) => ({
          id: p.id,
          name: p.name,
          area: p.area,
          description: p.description,
          imageUrl: p.image_url,
          googleMapsQuery: p.google_maps_query,
          matchedTags: (p.recommended_place_tags ?? []).map((rpt: any) => rpt.discovery_tags?.label).filter(Boolean),
          isSaved: savedMap.has(p.id),
          savedPlaceId: savedMap.get(p.id) ?? null,
        }));
      }
    }
  }

  return {
    id: walk.id,
    title: walk.title ?? '無題',
    location: walk.location,
    status: walk.status,
    createdAt: walk.created_at,
    completedAt: walk.completed_at,
    photos,
    selectedTags,
    recommendations,
  };
}

import { createClient } from '@/lib/supabase/server';
import { getSignedImageUrl } from '@/lib/images/getSignedImageUrl';

export interface HomeWalk {
  id: string;
  title: string;
  location: string | null;
  createdAt: string;
  coverImageUrl: string | null;
  selectedTags: string[];
}

export async function getCompletedWalks(): Promise<HomeWalk[]> {
  const supabase = await createClient();

  const { data: { user } } = await supabase.auth.getUser();
  if (!user) return [];

  const { data: walks, error } = await supabase
    .from('walks')
    .select(`
      id,
      title,
      location,
      created_at,
      walk_photos ( storage_path, sort_order ),
      discovery_tags ( label, selected )
    `)
    .eq('user_id', user.id)
    .eq('status', 'COMPLETED')
    .order('created_at', { ascending: false });

  if (error || !walks) return [];

  const result: HomeWalk[] = await Promise.all(
    walks.map(async (walk: any) => {
      // Cover photo: first by sort_order
      const photos = (walk.walk_photos ?? []).sort(
        (a: any, b: any) => a.sort_order - b.sort_order
      );
      let coverImageUrl: string | null = null;
      if (photos.length > 0) {
        try {
          coverImageUrl = await getSignedImageUrl(photos[0].storage_path, 3600);
        } catch {
          coverImageUrl = null;
        }
      }

      const selectedTags = (walk.discovery_tags ?? [])
        .filter((t: any) => t.selected)
        .map((t: any) => t.label);

      return {
        id: walk.id,
        title: walk.title ?? '無題',
        location: walk.location ?? null,
        createdAt: walk.created_at,
        coverImageUrl,
        selectedTags,
      };
    })
  );

  return result;
}
